const $=id=>document.getElementById(id),cv=$('stage'),ctx=cv.getContext('2d'),keys={},images={},types=['punch','dodge','jump','block','kick','airkick'];
const labels={punch:['GUARDIA','CARICAMENTO','ESTENSIONE','IMPATTO','RIENTRO','GUARDIA'],dodge:['GUARDIA','PREPARAZIONE','ARRETRAMENTO','SCHIVATA','RECUPERO','GUARDIA'],jump:['GUARDIA','CARICAMENTO','STACCO','IN VOLO','ATTERRAGGIO','GUARDIA'],block:['GUARDIA','CHIUSURA','PARATA','IMPATTO','RILASCIO','GUARDIA'],kick:['GUARDIA','CARICAMENTO','ESTENSIONE','CALCIO','RIENTRO','GUARDIA'],airkick:['GUARDIA','STACCO','IN VOLO','CALCIO AEREO','RIENTRO','GUARDIA']};
const timings={punch:[.07,.10,.08,.11,.10,.10],dodge:[.06,.09,.13,.22,.12,.10],jump:[.06,.14,.18,.24,.16,.10],block:[.06,.10,.16,.18,.10,.10],kick:[.07,.12,.09,.13,.10,.10],airkick:[.07,.12,.18,.16,.12,.10]};let ready=false,scrub=null,selected='punch',fighters,last=0,fx=[],botTimer=1.5,feedback='',comboQueue=[],comboIndex=0;

const comboLibrary=[
 {name:'Combo base',steps:[{type:'punch',label:'Pugno 1',damage:10},{type:'punch',label:'Pugno 2',damage:10},{type:'kick',label:'Calcio',damage:15}]},
 {name:'Assalto rapido',steps:[{type:'punch',label:'Pugno',damage:10},{type:'kick',label:'Calcio',damage:15},{type:'punch',label:'Pugno finale',damage:12}]},
 {name:'Calcio d’apertura',steps:[{type:'kick',label:'Calcio',damage:15},{type:'punch',label:'Pugno',damage:10},{type:'punch',label:'Pugno finale',damage:12}]},
 {name:'Attacco aereo',steps:[{type:'jump',label:'Salto',damage:0},{type:'airkick',label:'Calcio al volo',damage:18},{type:'punch',label:'Pugno a terra',damage:12}]},
 {name:'Schivata e risposta',steps:[{type:'dodge',label:'Schivata',damage:0},{type:'punch',label:'Contrattacco',damage:14},{type:'kick',label:'Calcio finale',damage:16}]},
 {name:'Parata e punizione',steps:[{type:'block',label:'Parata',damage:0},{type:'punch',label:'Punizione',damage:14},{type:'kick',label:'Chiusura',damage:16}]}
];
let selectedCombo=0,comboSteps=comboLibrary[0].steps;
function renderCombo(){const box=$('comboSequence');if(!box||!ready)return;box.innerHTML='';comboLibrary.forEach((combo,ci)=>{const group=document.createElement('div');group.className='combo-group'+(ci===selectedCombo?' selected':'');const title=document.createElement('button');title.className='combo-name';title.textContent=combo.name;title.onclick=()=>{selectedCombo=ci;comboSteps=combo.steps;renderCombo();$('comboInfo').textContent=combo.name+' selezionata'};group.append(title);const row=document.createElement('div');row.className='combo-row';combo.steps.forEach((step,n)=>{const card=document.createElement('button');card.className='combo-step';card.innerHTML='<strong>0'+(n+1)+'</strong><span>'+step.label+'</span><small>'+labels[step.type].slice(0,4).join(' · ')+'</small>';card.onclick=()=>{selected=step.type;scrub=0;fighters.forEach(f=>{f.active=false;f.type=step.type;f.frame=0});timeline();$('comboInfo').textContent=combo.name+' · '+step.label+' · '+labels[step.type].join(' · ')};row.append(card)});group.append(row);box.append(group)})}
function playCombo(){if(!ready)return;const id=Number($('comboFighter').value);comboQueue=[...comboSteps];comboIndex=0;comboQueue.id=id;comboQueue.next=()=>{if(comboIndex<comboQueue.length){const step=comboQueue[comboIndex++];action(id,step.type)}else comboQueue=[]};comboQueue.next();$('comboInfo').textContent='Riproduzione · '+comboLibrary[selectedCombo].name+' · '+comboSteps.map(s=>s.label).join(' → ')}
function stopCombo(){comboQueue=[];comboIndex=0;fighters.forEach(f=>{f.active=false;f.frame=0});$('comboInfo').textContent='Combo fermata'}
function reset(){comboQueue=[];comboIndex=0;fighters=[{x:490,hp:100,type:'punch',active:false,t:0,frame:0,hit:false,walk:0,blocking:false},{x:710,hp:100,type:'punch',active:false,t:0,frame:0,hit:false,walk:0,blocking:false}];scrub=null;fx=[];botTimer=1.5;$('loop').checked=false;message('Prova i movimenti o attiva il compagno');highlight(0)}
function message(s){feedback=s;$('message').textContent=s}
function frameAt(type,t){let sum=0;for(let i=0;i<6;i++){sum+=timings[type][i];if(t<sum)return i}return 5}
function action(id,type=selected){if(!ready||fighters[id].active)return;scrub=null;let f=fighters[id];f.type=type;f.active=true;f.frame=0;f.t=0;f.hit=false;f.blocking=false}
function compare(){if(!ready)return;fighters.forEach((f,i)=>{f.active=false;action(i)})}
function poseImage(id,type,frame){if(type==='kick')return frame===0||frame===5?images.punch[id][0]:images.study[id][4];if(type==='airkick'){if(frame===0||frame===5)return images.punch[id][0];if(frame===1)return images.jump[id][1];if(frame===2||frame===3)return images.study[id][4];return images.jump[id][4]}return images[type][id][frame]}
function highlight(n){document.querySelectorAll('.frame').forEach((el,i)=>{el.classList.toggle('active',i===n);el.setAttribute('aria-pressed',String(i===n))})}
function timeline(){document.querySelectorAll('.move').forEach(b=>b.classList.toggle('accent',b.dataset.move===selected));$('frames').innerHTML='';for(let i=0;i<6;i++){let b=document.createElement('button');b.className='frame';b.setAttribute('aria-label','Fotogramma '+(i+1)+' '+labels[selected][i]);let img=poseImage(0,selected,i);b.innerHTML=`<img src="${img?.src||''}" alt=""><span>0${i+1} / ${labels[selected][i]}</span>`;b.onclick=()=>{if(!ready)return;scrub=i;fighters.forEach(f=>{f.active=false;f.type=selected;f.frame=i});$('loop').checked=false;highlight(i);message('Fotogramma 0'+(i+1)+' · '+labels[selected][i].toLowerCase())};$('frames').append(b)}highlight(0)}
function select(type){selected=type;scrub=null;timeline()}
function hit(a,b,damage){const target=fighters[b],attacker=fighters[a];if(Math.abs(attacker.x-target.x)>(attacker.type==='kick'?270:245)){message('Colpo a vuoto · Avvicinati');return}if(target.active&&target.type==='dodge'&&target.frame>=2&&target.frame<=3){message('Schivata riuscita · Nessun danno');return}if(target.active&&target.type==='jump'&&target.frame>=2&&target.frame<=3){message('Colpo evitato in salto');return}const block=target.active&&target.type==='block'&&target.frame>=2&&target.frame<=3;target.hp=Math.max(0,target.hp-(block?0:damage));fx.push({x:(attacker.x+target.x)/2,y:330,t:.25,blocked:block});message(block?'Parata riuscita · Nessun danno':'Colpo a segno · −'+damage+' vita');if(!target.hp)message('Bersaglio esaurito · Ripristina per riprovare')}
function step(dt){if(!ready||scrub!==null)return;let scaled=dt*Number($('speed').value);
 // Update both poses before resolving impacts, for simultaneous defensive inputs.
 fighters.forEach((f,i)=>{let mv=i?Number(!!keys.arrowright)-Number(!!keys.arrowleft):Number(!!keys.d)-Number(!!keys.a);if(!f.active){f.x+=mv*190*scaled;f.walk=mv?f.walk+scaled:0;f.x=Math.max(155,Math.min(1045,f.x))}if(f.active){f.t+=scaled;f.frame=frameAt(f.type,f.t);if(f.type==='block'&&(i?keys.arrowdown:keys.s)&&f.frame>=3){f.t=timings.block.slice(0,3).reduce((a,b)=>a+b,0);f.frame=3;f.blocking=true}if(f.t>=timings[f.type].reduce((a,b)=>a+b,0)){f.active=false;f.frame=0;f.t=0;f.blocking=false;if(comboQueue&&comboQueue.id===i)comboQueue.next()}}});
 fighters.forEach((f,i)=>{if(f.active&&['punch','kick'].includes(f.type)&&f.frame>=3&&!f.hit){f.hit=true;hit(i,1-i,f.type==='kick'?15:10)}});
 let[a,b]=fighters;if(Math.abs(a.x-b.x)<170){let mid=(a.x+b.x)/2;a.x=mid-85;b.x=mid+85}
 if($('partner').checked){botTimer-=scaled;if(botTimer<=0){botTimer=1.7;action(1,'punch')}}
 if($('loop').checked&&!fighters.some(f=>f.active))compare();fx.forEach(e=>e.t-=dt);fx=fx.filter(e=>e.t>0);highlight(fighters.find(f=>f.active&&f.type===selected)?.frame??0)}
function background(){let g=ctx.createLinearGradient(0,0,0,600);g.addColorStop(0,'#e7dfd4');g.addColorStop(1,'#c8b7a0');ctx.fillStyle=g;ctx.fillRect(0,0,1200,600);ctx.strokeStyle='#bda99155';ctx.lineWidth=2;for(let x=80;x<1200;x+=208){ctx.strokeRect(x,105,180,355);ctx.beginPath();ctx.moveTo(x+90,105);ctx.lineTo(x+90,460);ctx.stroke()}ctx.fillStyle='#d7c8b5';ctx.fillRect(0,460,1200,140);ctx.fillStyle='#b8a68f';ctx.fillRect(0,460,1200,5);ctx.strokeStyle='#baa78e66';for(let x=-1000;x<2500;x+=180){ctx.beginPath();ctx.moveTo(600+(x-600)*.25,465);ctx.lineTo(x,600);ctx.stroke()}for(let y of[485,520,570]){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1200,y);ctx.stroke()}ctx.font='100px Georgia';ctx.textAlign='center';ctx.fillStyle='#aa8e7520';ctx.fillText('ECLIPSE',600,260)}
function draw(){background();if(!ready)return;fighters.forEach((f,i)=>{let frame=scrub??f.frame,type=scrub!==null?selected:f.active?f.type:'punch',img=poseImage(i,type,frame);if(!f.active&&scrub===null&&f.walk>0&&Math.floor(f.walk*8)%2)img=images.study[i][1];ctx.save();ctx.translate(f.x,557);ctx.scale(i?-1:1,1);let punchAsset=img.src.includes('/punch/');let width=punchAsset?270:324,height=punchAsset?405:459;if(type==='kick'&&f.active&&frame>0&&frame<5){let phase=frame===3?1:frame===2||frame===4?.6:.15;ctx.globalAlpha=phase;ctx.drawImage(img,-width/2,-height,width,height);ctx.globalAlpha=1-phase;ctx.drawImage(images.punch[i][0],-135,-405,270,405);ctx.globalAlpha=1}else ctx.drawImage(img,-width/2,-height,width,height);ctx.restore();$('hp'+i).style.width=f.hp+'%'});fx.forEach(e=>{ctx.strokeStyle=e.blocked?'#416775':'#a43e2d';ctx.lineWidth=3;ctx.globalAlpha=Math.min(1,e.t*6);for(let i=0;i<8;i++){let a=i*Math.PI/4,r=(.25-e.t)*180;ctx.beginPath();ctx.moveTo(e.x+Math.cos(a)*r,e.y+Math.sin(a)*r);ctx.lineTo(e.x+Math.cos(a)*(r+12),e.y+Math.sin(a)*(r+12));ctx.stroke()}ctx.globalAlpha=1})}
$('punch0').onclick=()=>action(0);$('punch1').onclick=()=>action(1);$('both').onclick=compare;$('reset').onclick=reset;$('loop').onchange=()=>{if($('loop').checked)compare()};document.querySelectorAll('.move').forEach(b=>b.onclick=()=>select(b.dataset.move));
const mapping={u:[0,'punch'],i:[0,'kick'],q:[0,'dodge'],w:[0,'jump'],s:[0,'block'],j:[1,'punch'],k:[1,'kick'],l:[1,'dodge'],arrowup:[1,'jump'],arrowdown:[1,'block'],o:[0,'airkick'],m:[1,'airkick']};
function keyDown(k){if(!keys[k]&&mapping[k])action(...mapping[k]);keys[k]=true}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;let k=e.key.toLowerCase();if(mapping[k]||['a','d','arrowleft','arrowright',' '].includes(k))e.preventDefault();keyDown(k);if(k===' '&&!e.repeat)compare()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keyDown(b.dataset.key)};for(let evt of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(evt,()=>keys[b.dataset.key]=false)});
reset();
const loads=[];
for(const type of ['punch','dodge','jump','block','study']){images[type]=[[],[]];for(let r=0;r<2;r++)for(let n=0;n<6;n++)loads.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[type][r][n]=im;resolve()};im.onerror=reject;im.src=`assets-alpha/${type}/${r}-${n}.png`}))}
Promise.all(loads).then(()=>{ready=true;timeline();renderCombo();$('loading').style.display='none'}).catch(()=>{$('loading').textContent='Impossibile caricare le immagini. Ricarica la pagina.'});

const simCanvas=$('simStage'),simCtx=simCanvas?.getContext('2d');let sim={run:false,t:0,hp:[100,100],round:1,score:[0,0],turn:0,last:0,flash:0,attacker:0};
function simReset(){sim={run:false,t:0,hp:[100,100],round:1,score:[0,0],turn:0,last:performance.now(),flash:0,attacker:0};if($('simInfo'))$('simInfo').textContent='Premi “Avvia simulazione” per iniziare';simDraw()}
function simStart(){if(sim.score[0]>=2||sim.score[1]>=2)simReset();sim.run=true;sim.last=performance.now();if($('simInfo'))$('simInfo').textContent='Simulazione in corso · Round '+sim.round}
function simHit(){const attacker=sim.turn,target=attacker?0:1;sim.attacker=attacker;sim.flash=performance.now();sim.hp[target]=Math.max(0,sim.hp[target]-(attacker===0?12:10));sim.turn=target;if(sim.hp[target]===0){sim.score[attacker]++;if(sim.score[attacker]>=2){sim.run=false;$('simInfo').textContent=(attacker===0?'Demone':'Ninja')+' vince la simulazione · Premi Reset per riprovare'}else{sim.round++;sim.hp=[100,100];sim.turn=attacker;$('simInfo').textContent='Round '+sim.round+' · '+(attacker===0?'Demone':'Ninja')+' ha vinto il round'}}}
function simDraw(){if(!simCtx)return;const w=simCanvas.width,h=simCanvas.height,now=performance.now(),pulse=Math.max(0,1-(now-sim.flash)/380),move=pulse*(sim.attacker===0?30:-30);simCtx.clearRect(0,0,w,h);simCtx.fillStyle='#101516';simCtx.fillRect(0,0,w,h);simCtx.fillStyle='#222b2b';simCtx.fillRect(0,215,w,65);simCtx.fillStyle='#ddb167';simCtx.fillRect(22,22,220*sim.hp[0]/100,10);simCtx.fillStyle='#6c9ca3';simCtx.fillRect(w-242,22,220*sim.hp[1]/100,10);simCtx.fillStyle='#eadfcf';simCtx.font='bold 12px sans-serif';simCtx.fillText('DEMONE  '+sim.hp[0]+'%',22,17);simCtx.textAlign='right';simCtx.fillText(sim.hp[1]+'%  NINJA',w-22,17);simCtx.textAlign='center';simCtx.font='bold 13px sans-serif';simCtx.fillText('ROUND '+sim.round+'   ·   '+sim.score[0]+' — '+sim.score[1],w/2,30);if(ready){const a=images.punch[0][0],b=images.punch[1][0];if(a)simCtx.drawImage(a,105+move,55,150,225);if(b)simCtx.save(),simCtx.translate(w-105+move,0),simCtx.scale(-1,1),simCtx.drawImage(b,-255,55,150,225),simCtx.restore()}if(pulse){simCtx.fillStyle='#ddb167';simCtx.font='bold 16px sans-serif';simCtx.fillText('IMPATTO!',w/2,105)}simCtx.fillStyle='#ddb167';simCtx.font='11px sans-serif';simCtx.fillText(sim.run?'COLPI AUTOMATICI · MOVIMENTO · ROUND':'SIMULAZIONE FERMA',w/2,258)}
function simTick(ms){if(sim.run&&ms-sim.last>900){simHit();sim.last=ms}simDraw();requestAnimationFrame(simTick)}
$('simStart')?.addEventListener('click',simStart);$('simReset')?.addEventListener('click',simReset);simReset();requestAnimationFrame(simTick);
function tick(ms){let dt=Math.min((ms-last)/1000,.04);last=ms;step(dt);draw();requestAnimationFrame(tick)}requestAnimationFrame(tick);

$('comboPlay')?.addEventListener('click',playCombo);$('comboStop')?.addEventListener('click',stopCombo);$('comboFighter')?.addEventListener('change',()=>renderCombo());
